Theorem apply_site_full : forall ma mb mc md me mf mg mh fr vlo vhi lo hi,
  kfr_le1 fr -> int_wrap 32 vlo = lo -> 0 <= lo <= 255 -> int_wrap 32 vhi = hi -> 0 <= hi <= 255 ->
  let frd := fst (fp_convert fmt_single fmt_double ma fr) in
  let t1 := fst (fp_sub fmt_double mb p_one_d frd) in
  let lod := fst (fp_of_int fmt_double mc false 32 vlo) in
  let his := fst (fp_of_int fmt_single md false 32 vhi) in
  let t2 := fst (fp_mul fmt_single me fr his) in
  let t2d := fst (fp_convert fmt_single fmt_double mf t2) in
  let t3 := fst (fp_fma fmt_double mg t1 lod t2d) in
  let v := fst (fp_add fmt_double mh t3 p_half_d) in
  0 <= fr < 2 ^ 32 /\ 0 <= frd < 2 ^ 64 /\ 0 <= t1 < 2 ^ 64 /\ 0 <= lod < 2 ^ 64 /\ 0 <= his < 2 ^ 32 /\ 0 <= t2 < 2 ^ 32 /\ 0 <= t2d < 2 ^ 64 /\
  0 <= t3 < 2 ^ 64 /\ 0 <= v < 2 ^ 64 /\
  fst (fp_lt fmt_double p_lo_d v) = true /\ fst (fp_lt fmt_double v p_hi_d) = true /\ 0 <= fst (fp_to_int fmt_double RTZ true 32 v) < 512.
Proof.
